#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Battle;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using TMPro;
using UnityEditor;
using UnityEngine;
namespace LastRail.Tests.EditMode {
 public class EquipmentMultishotPreviewBindingTests {
  static JObject Entry()=>((JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/MiraEquipped-20261016/PlacementPreviewSource/server-packets.json"))["packets"]["grown"]);
  static EquipmentMultishotPlacementPreviewModel Preview(string key){var e=Entry();var p=(JObject)e["previews"][key];return EquipmentMultishotPlacementPreviewModel.Read(p,p,BDirectAttackInput.Digest(p),"a","LOCAL_B12_RUN",(JObject)e["previewCommands"][key]);}
  static EquipmentMultishotModel Source(JObject p)=>EquipmentMultishotModel.Read(p,p,BDirectAttackInput.Digest(p),"a","LOCAL_B12_RUN");
  static Task Refresh(EquipmentMultishotController controller,Func<CancellationToken,Task<EquipmentMultishotPlacementPreviewModel>> read){var method=typeof(EquipmentMultishotController).GetMethod("RefreshPreviewAsync");Assert.That(method,Is.Not.Null,"Existing display controller preview binding missing");return (Task)method.Invoke(controller,new object[]{read});}
  static void Clear(EquipmentMultishotController controller){var method=typeof(EquipmentMultishotController).GetMethod("ClearPreview");Assert.That(method,Is.Not.Null);method.Invoke(controller,null);}
  [Test]public async Task ActualPreviewDoesNotReplaceCurrentOrOriginalDeparture(){using var c=new EquipmentMultishotController("a","LOCAL_B12_RUN");JObject frame=null;c.Bind(v=>frame=v,()=>{});var e=Entry();await c.RefreshAsync("CURRENT_VERIFIED_EQUIPMENT",_=>Task.FromResult(Source((JObject)e["previews"]["swap"]["before"])));await c.RefreshAsync("ORIGINAL_LOCAL_TRIAL_START",_=>Task.FromResult(Source((JObject)e["presentations"]["one"]["departure"])));var current=frame["current"].DeepClone();var frozen=frame["departure"].DeepClone();await Refresh(c,_=>Task.FromResult(Preview("remove")));Assert.That((string)frame["preview"]["after"]["summary"],Does.Contain("15%"));Assert.That(JToken.DeepEquals(current,frame["current"]),Is.True);Assert.That(JToken.DeepEquals(frozen,frame["departure"]),Is.True);Clear(c);Assert.That(frame["preview"].Type,Is.EqualTo(JTokenType.Null));Assert.That(JToken.DeepEquals(frozen,frame["departure"]),Is.True);}
  [TestCase("swap")][TestCase("replace")][TestCase("upgraded")][TestCase("unsupported")][TestCase("alreadyCommitted")]
  public async Task ActualOwnerResultsRenderAsPreviewOrOriginalReplay(string key){using var c=new EquipmentMultishotController("a","LOCAL_B12_RUN");JObject frame=null;c.Bind(v=>frame=v,()=>{});await Refresh(c,_=>Task.FromResult(Preview(key)));Assert.That(frame["preview"].Type,Is.EqualTo(JTokenType.Object));Assert.That((bool)frame["preview"]["appliesToCombat"],Is.False);if(key=="alreadyCommitted"){Assert.That(frame["preview"]["before"].Type,Is.EqualTo(JTokenType.Null));Assert.That(frame["preview"]["after"].Type,Is.EqualTo(JTokenType.Null));}if(key=="unsupported")Assert.That((string)frame["preview"]["after"]["summary"],Is.EqualTo("효과 상태 확인 불가"));if(key=="upgraded")Assert.That(((JArray)frame["preview"]["after"]["slots"]).Any(r=>(string)r["currentStar"]=="장비 ★2"&&(string)r["appliedStar"]=="시술 당시 ★1"&&(string)r["coefficient"]=="추가 피해15%"),Is.True);}
  [Test]public async Task PreviewFromDifferentDepartureCannotOverwriteBoundOriginal(){using var c=new EquipmentMultishotController("a","LOCAL_B12_RUN");JObject frame=null;c.Bind(v=>frame=v,()=>{});var e=Entry();await c.RefreshAsync("ORIGINAL_LOCAL_TRIAL_START",_=>Task.FromResult(Source((JObject)e["presentations"]["one"]["departure"])));var frozen=frame["departure"].DeepClone();var p=(JObject)e["previews"]["swap"].DeepClone();p["before"]["departurePinHash"]=new string('0',64);p["after"]["departurePinHash"]=new string('0',64);var different=EquipmentMultishotPlacementPreviewModel.Read(p,p,BDirectAttackInput.Digest(p),"a","LOCAL_B12_RUN",(JObject)e["previewCommands"]["swap"]);await Refresh(c,_=>Task.FromResult(different));Assert.That(frame["preview"].Type,Is.EqualTo(JTokenType.Null));Assert.That((string)frame["previewNotice"],Is.Not.Empty);Assert.That(JToken.DeepEquals(frozen,frame["departure"]),Is.True);}
  [Test]public async Task FailedOrUnboundPreviewCannotKeepAStaleCandidate(){using var c=new EquipmentMultishotController("a","LOCAL_B12_RUN");JObject frame=null;c.Bind(v=>frame=v,()=>{});await Refresh(c,_=>Task.FromResult(Preview("swap")));await Refresh(c,_=>Task.FromException<EquipmentMultishotPlacementPreviewModel>(new InvalidOperationException("equipment_revision_conflict")));Assert.That(frame["preview"].Type,Is.EqualTo(JTokenType.Null));Assert.That((string)frame["previewNotice"],Is.Not.Empty);var pending=new TaskCompletionSource<EquipmentMultishotPlacementPreviewModel>();var task=Refresh(c,_=>pending.Task);c.Unbind();var before=frame.DeepClone();pending.SetResult(Preview("swap"));await task;Assert.That(JToken.DeepEquals(before,frame),Is.True);}
  [Test]public async Task ExistingPopupSeparatesBeforeAfterExpectedStatsAndUncommittedStatus(){var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/_LASTRAIL/UI/Fonts/Pretendard/TMP/Pretendard-Regular SDF.asset");var canvas=new GameObject("EN17PreviewPopup",typeof(RectTransform),typeof(Canvas));var pages=LobbyDestinationPages.Create(canvas.transform,font,()=>{});using var c=new EquipmentMultishotController("a","LOCAL_B12_RUN");try{pages.Open(LobbyPage.Operators,true);c.Bind(pages);await Refresh(c,_=>Task.FromResult(Preview("replace")));var text=pages.GetComponentsInChildren<TMP_Text>();Assert.That(text.Single(t=>t.name=="PreviewStatus").text,Is.EqualTo("확정 전 미리보기"));Assert.That(text.Single(t=>t.name=="previewBeforeBasis").text,Is.EqualTo("장착 전"));Assert.That(text.Single(t=>t.name=="previewAfterBasis").text,Is.EqualTo("장착 후 예상"));Assert.That(text.Single(t=>t.name=="PreviewBeforeAttack").text,Does.StartWith("ATK "));Assert.That(text.Single(t=>t.name=="PreviewAfterAttack").text,Does.StartWith("ATK "));Assert.That(text.Any(t=>t.name=="departureBasis"),Is.False);}finally{c.Unbind();UnityEngine.Object.DestroyImmediate(canvas);}}
 }
}
#endif
